import type {
  CanonicalCalculationDocumentV1,
  CanonicalQuoteSnapshotV1,
} from "../../lib/quotes/canonical-snapshot.ts";

export type CanonicalV1Vector = {
  name: string;
  currencyExponent: 0 | 2 | 3;
  calculation: CanonicalCalculationDocumentV1;
  snapshot: CanonicalQuoteSnapshotV1;
  expectedCalculationHash: string;
  expectedSnapshotHash: string;
};

function snapshotFor(
  revisionNumber: number,
  calculation: CanonicalCalculationDocumentV1,
  fingerprint: string,
  overrides: Partial<CanonicalQuoteSnapshotV1> = {},
): CanonicalQuoteSnapshotV1 {
  return {
    format_version: 1,
    quote: {
      id: `10000000-0000-4000-8000-${String(revisionNumber).padStart(12, "0")}`,
      number: `TND-2026-${String(revisionNumber).padStart(4, "0")}`,
      revision_number: revisionNumber,
      parent_snapshot_hash: null,
    },
    seller: {
      legal_name: "Tender Seller Pvt Ltd",
      address_line1: "1 Market Road",
      address_line2: "",
      city: "Mumbai",
      region: "MH",
      postal_code: "400001",
      country_code: "IN",
      tax_identifier: null,
      contact_email: "sales@example.test",
      contact_phone: null,
    },
    buyer: {
      customer_id: `20000000-0000-4000-8000-${String(revisionNumber).padStart(12, "0")}`,
      name: "Buyer",
      contact_name: "",
      email: "buyer@example.test",
      address_line1: "",
      address_line2: "",
      city: "",
      region: "",
      postal_code: "",
      country_code: "IN",
      tax_identifier: null,
    },
    commercial: {
      currency_code: calculation.currency_code,
      locale: "en-IN",
      tax_label: "Tax",
      tax_mode: calculation.tax_mode,
      customer_tax_treatment: "standard",
      discount_bps: calculation.discount_bps,
      issue_date: "2026-08-14",
      valid_until: "2026-09-14",
      notes: "",
    },
    items: [],
    charges: [],
    totals: calculation.totals,
    approval_policy: {
      threshold_bps: 1000,
      requires_manual_approval: false,
      reason_codes: [],
    },
    calculation: { format_version: 1, fingerprint },
    ...overrides,
  };
}

